package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.ViewController; import com.innovatus.studentrecords.model.Student; import com.innovatus.studentrecords.service.SessionManager; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import javax.swing.table.*; import java.awt.*; import java.util.*; public class ViewRecordsFrame extends BaseFrame {public ViewRecordsFrame(){super("View Records");JTextField q=new JTextField(18);JButton go=button("Search / Refresh");DefaultTableModel m=new DefaultTableModel(new String[]{"Roll","Name","Department","Year","Batch","Semester","Mobile","Email"},0){public boolean isCellEditable(int r,int c){return false;}};JTable t=new JTable(m);t.setAutoCreateRowSorter(true);JPanel top=new JPanel();top.add(new JLabel("Roll number or name:"));top.add(q);top.add(go);add(top,BorderLayout.NORTH);add(new JScrollPane(t));go.addActionListener(e->{try{m.setRowCount(0);for(Student s:new ViewController().find(SessionManager.user().id(),q.getText(),"","","",""))m.addRow(new Object[]{s.rollNo(),s.name(),s.department(),s.year(),s.batch(),s.semester(),s.mobile(),s.email()});}catch(Exception x){DialogUtil.error(this,x.getMessage());}});go.doClick();}}
